Connection: keep-alive
Content-Length: 54

{"userName":"admin","password":"123456","code":"__captcha__"}

`

// 全局定义要访问的接口类型
// 可选值: reg2, reg, reg00, reg01, reg02, reg03, reg04, reg05, reg06, reg000
global_api := "reg03"

global_server := "http://127.0.0.1:8888"
global_authorization := "Basic f0ngauth"

// ==================================================== 代码主体，WebFuzzer 热加载复制以下代码即可 ======================================
// 全局变量：获取目标站点的图形验证码的 image，可以通过刷新验证码，获取对应 URL。
var target_image_url = "https://beip.xxx.com/system/api/v1/getVlidateCode?radomCode=4195a147-6fb8-66ef-5cb4-fa6c49c69ef1"

// get_dddocr：请求本地 Pyhton 服务器，获取图形验证码识别后，返回的字符串。
// byte_image String: 传入 image base64 编码后的数据。
// return String: 验证码识别后，返回识别的字符串。
get_dddocr = (base64_image) => {
    // OCR接口：获取 OCR 服务获取识别后的验证码
    // 根据全局定义的接口选择对应的路径
    path := ""
    switch global_api {
        case "reg2":
            path = "reg2"      // 识别算术验证码（如 3+5=?）
        case "reg":
            path = "reg"       // 识别常规验证码（通用模式）
        case "reg00":
            path = "reg00"     // 识别纯整数 0-9
        case "reg01":
            path = "reg01"     // 识别纯小写英文 a-z
        case "reg02":
            path = "reg02"     // 识别纯大写英文 A-Z
        case "reg03":
            path = "reg03"     // 识别小写英文 a-z + 大写英文 A-Z
        case "reg04":
            path = "reg04"     // 识别小写英文 a-z + 整数 0-9
        case "reg05":
            path = "reg05"     // 识别大写英文 A-Z + 整数 0-9
        case "reg06":
            path = "reg06"     // 识别小写英文 a-z + 大写英文 A-Z + 整数 0-9
        case "reg000":
            path = "reg000"    // 识别自定义字符（默认算术，可扩展）
        default:
            log.Info("指定 OCR 识别接口不存在。")
    }

    target, _ := str.UrlJoin(global_server, path)
    // dump(target)

    OCR_rsp, OCR_req, _ := poc.Post(target,
        poc.appendHeader("Authorization", global_authorization),
        poc.postData(base64_image)
    )
    rsp_body := OCR_rsp.GetBody()    // 返回的验证码，如 fwgx
    // dump(rsp_body)

    return rsp_body
}


// get_image 获取验证码，如果验证码接口返回的不是标准的二进制数据流，需要对该函数进行修改。
get_image = (target_url, req) => {
    var base64_image
    // 1.获取当前请求 Cookie 确保获取验证码的请求和登录请求保持在一个 session 内。
    cookie := re.Find(req, `(?i)cookie`)
    session := poc.GetHTTPPacketHeader(req, cookie)
    // 如果验证码接口返回的不是标准的二进制数据流，需要对 imageRsp 进行针对性处理
    imageRsp, imageReq, _ = poc.Get(target_image_url, poc.appendHeader(cookie, session))

    if str.Contains(imageRsp.GetContentType(), "image/jpeg") {
        // 场景一：标准的 image 二进制流
        base64_image = codec.EncodeBase64(imageRsp.GetBody())
    }


    if str.Contains(imageRsp.GetContentType(), "application/json") {
        // 场景二：json 形式的响应体
        base64_image = json.loads(imageRsp.GetBody())["image"]  // image 可以替换为响应体中包含 image base64 编码的字符串。
    }

    captcha := get_dddocr(base64_image)

    return captcha
}

// beforeRequest 允许在每次发送数据包前对请求做最后的处理，定义为 func(https bool, originReq []byte, req []byte) []byte
// https 请求是否为https请求
// originReq 原始请求
// req 请求
beforeRequest = func(https, originReq, req) {
    captcha := get_image(target_image_url, req)

    // 发送请求前替换原始请求验证码。
    req = str.ReplaceAll(req, "__captcha__", captcha)
    // dump(req)

    // 将修改后的请求返回
    return []byte(req)
}

